// Pro/Premium build-time entitlement config.
//
// Generated by `node scripts/set-release-channel.js` for a real release
// build — do not hand-edit this file for a release; run the script instead
// (`npm run channel:website` / `npm run channel:google-play`, see BUILD.md
// and docs/06_RELEASE_CHANNEL_CONTRACT.md).
//
// This checked-in default deliberately leaves ENTITLEMENT_CHANNEL unset (and
// bakes in no API URL or license key) so that opening index.html directly,
// or a plain `cap run android` / `npm run build:windows` without running the
// channel script first, is never accidentally unlocked. isProLocked() in
// www/index.html treats an unset/unrecognized channel the same as
// GOOGLE_PLAY: permanently locked, no purchase flow — only
// `channel:website` produces a build that can actually be unlocked, via a
// real Niagara Indie Apps license key (see www/license-client.js).
window.PRO_LOCKS_ENABLED = true;
